#include <iostream>
int base = 2;
int scale(int x, int k = base) { return x * k; }
int &pick(int &a, int &b) { return a > b ? a : b; }
int main() {
    int p = 3, q = 7;
    pick(p, q) = scale(p);
    base = 10;
    std::cout << p << " " << q << " " << scale(1) << "\n";
    return 0;
}

#include <iostream>
namespace bank { int rate = 5; int interest(int p) { return p * rate / 100; } }
namespace loan { int rate = 12; }
int rate = 1;
int main() {
    using bank::interest;
    int rate = 99;
    std::cout << interest(200) << " " << loan::rate << " " << ::rate << " " << rate << "\n";
    return 0;
}

