The file below is compiled once as C (C11) and once as C++ (C++17) on a system where int is 4 bytes. What does it print in each case?

#include <stdio.h>
int main(void) {
    printf("%zu", sizeof('A'));
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
namespace A { int x = 1; }
namespace B { int x = 2; }
int x = 3;
int main() {
    int x = 4;
    std::cout << A::x << B::x << ::x << x;
    return 0;
}

What happens when the following C++ program is compiled and run?

#include <iostream>
namespace A { int v = 1; }
namespace B { int v = 2; }
using namespace A;
using namespace B;
int main() {
    std::cout << v;
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
namespace Outer {
    int f() { return 3; }
    namespace Inner { int f() { return 7; } }
}
namespace OI = Outer::Inner;
int main() {
    std::cout << OI::f() * Outer::f();
    return 0;
}

What happens when the following C++ program is compiled?

#include <iostream>
using std::cout;
int main() {
    int n = 0;
    cin >> n;      // (1)
    cout << n;     // (2)
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
int n = 10;
int main() {
    int n = 20;
    {
        int n = 30;
        std::cout << n << " " << ::n;
    }
    std::cout << " " << n;
    return 0;
}

What does the following fragment print? It runs inside main() with <iostream> included.

int a = 5;
int &r = a;
r++;
a *= 2;
std::cout << a << " " << r;

What does the following fragment print? It runs inside main() with <iostream> included.

int a = 1, b = 2;
int &r = a;
r = b;
b = 5;
std::cout << a << " " << b << " " << r;

What is the output of the following C++ program?

#include <iostream>
void f(int v, int *p, int &r) {
    v += 1; *p += 2; r += 3;
}
int main() {
    int a = 0, b = 0, c = 0;
    f(a, &b, c);
    std::cout << a << b << c;
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
int &counter() {
    static int c = 0;
    return ++c;
}
int main() {
    counter() = 10;
    counter();
    std::cout << counter();
    return 0;
}

What does the following fragment print? It runs inside main() with <iostream> included.

double d = 3.7;
const int &r = d;
d = 9.9;
std::cout << r << " " << d;

Only these two overloads of f are declared. Which of the calls f(5), f(5L), f(5.0f) and f('a') fail to compile because they are ambiguous?

#include <iostream>
void f(long x)   { std::cout << "L"; }
void f(double x) { std::cout << "D"; }

What is the output of the following C++ program?

#include <iostream>
void h(int x)   { std::cout << "I"; }
void h(char *p) { std::cout << "P"; }
int main() {
    h(0);
    h(nullptr);
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
void f(int &x)       { std::cout << "L"; }
void f(const int &x) { std::cout << "C"; }
int main() {
    int a = 1;
    const int b = 2;
    f(a); f(b); f(a + b);
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
void f(int)    { std::cout << "I"; }
void f(char)   { std::cout << "C"; }
void f(double) { std::cout << "D"; }
int main() {
    char c = 'a';
    short s = 2;
    f(c + 1); f(s); f(true); f(c);
    return 0;
}

What happens when the following C++ program is compiled and run?

#include <iostream>
void p(int a)            { std::cout << a; }
void p(int a, int b = 0) { std::cout << a + b; }
int main() {
    p(1, 2);
    p(1);
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
int g = 1;
int f(int x = g) { return x * 10; }
int main() {
    std::cout << f() << " ";
    g = 5;
    std::cout << f() << " " << f(2);
    return 0;
}

The following C++ program is compiled. Which marked line, if any, causes a compile error?

#include <iostream>
int area(int l, int b = 2);       // (1)
int area(int l, int b = 2) {      // (2)
    return l * b;
}
int main() {
    std::cout << area(3);         // (3)
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
int calc(int a, int b = 2) { return a * b; }
double calc(double a)      { return a / 2; }
int main() {
    std::cout << calc(5) << " " << calc(5.0) << " " << calc(calc(3), 4);
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
namespace S { int a = 4; }
namespace S { int b = a * 2; }
int main() {
    std::cout << S::a + S::b;
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
#define CUBE(x) (x * x * x)
inline int cube(int x) { return x * x * x; }
int main() {
    std::cout << CUBE(1 + 1) << " " << cube(1 + 1);
    return 0;
}

What is the output of the following C++ program?

#include <iostream>
#define MAX(a, b) ((a) > (b) ? (a) : (b))
inline int imax(int a, int b) { return a > b ? a : b; }
int main() {
    int i = 5, j = 3, k = 5;
    int m1 = MAX(i++, j);
    int m2 = imax(k++, j);
    std::cout << m1 << " " << i << " " << m2 << " " << k;
    return 0;
}

