std::cin >> a >> b;
std::cout << b << "," << a;

What does the following fragment print? It runs inside main() with <iostream> included.

char c = 'A';
bool ok = 5 > 3;
std::cout << 5 + 3 << " " << ok << " " << c + 1 << " " << c;

What does the following fragment print? It runs inside main() with <iostream> included.

int *p = new int(4);
int *q = new int[4]();
std::cout << *p + q[3];
delete p;
delete[] q;

What is the output of the following C++ program?

#include <cstdlib>
#include <iostream>
struct T {
    T()  { std::cout << "C"; }
    ~T() { std::cout << "D"; }
};
int main() {
    T *a = new T[2];
    T *b = static_cast<T *>(std::malloc(sizeof(T)));
    delete[] a;
    std::free(b);
    return 0;
}
